        (unsigned)BICYCLE_DEMO_RANDOM_WARMUP_MS,
        (unsigned)DEMO_RANDOM_HOP_N, (unsigned)BICYCLE_DEMO_RANDOM_PERIOD_MS);
    return BICYCLE_DEMO_OK;
