{"file_path": "/home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/my_vendor/ui/bicycle/src/bicycle_gpx_sim.c", "new_string": "/**
 * @brief 演示：把东/北偏移折算进经纬度（等距圆柱近似；只用于几十一百米的横移）。
 */
static void sim_apply_offset(bicycle_gnss_fix_t * fix)
{
    double coslat;

    if (fix == NULL || !fix->valid
        || (s_sim_off_east_m == 0.0 && s_sim_off_north_m == 0.0)) {
        return;
    }

    coslat = cos((double)fix->latitude * M_PI / 180.0);
    if (coslat < 0.1) {
        coslat = 0.1;
    }

    fix->latitude = (float)((double)fix->latitude
        + s_sim_off_north_m / 111320.0);
    fix->longitude = (float)((double)fix->longitude
        + s_sim_off_east_m / (111320.0 * coslat));
}

bool bicycle_gpx_sim_get_fix(bicycle_gnss_fix_t * out)
{
    bool from_gpx = false;
    bool have;

    if (out == NULL) {
        return false;
    }

    /* 全国跳优先（见上面那段）：它是"最大渲染负载"的定位源，专供 A/B 用。 */
    if (bicycle_gnss_hop_get_fix(out)) {
        have = true;
    } else if (route_sim_get_fix(out)) {
        have = true;
    } else if (g_sim.thread_run) {
        pthread_mutex_lock(&g_sim.lock);
        *out = g_sim.fix;
        pthread_mutex_unlock(&g_sim.lock);
        have = out->valid;
        from_gpx = have;
    } else {
        have = false;
    }

    if (!have) {
        return false;
    }

    /* 暂停演示：回放位置冻住 + 速度报 0（只认 GPX 回放，别把路线 sim 也冻了）。 */
    if (from_gpx && g_sim.hold) {
        out->speed_kph = 0.0f;
        out->speed_pvt_kph = 0.0f;
        out->alive = true;
        out->valid = true;
    }

    sim_apply_offset(out);
    return true;
}", "old_string": "bool bicycle_gpx_sim_get_fix(bicycle_gnss_fix_t * out)
{
    /* 全国跳优先（见上面那段）：它是"最大渲染负载"的定位源，专供 A/B 用。 */
    if (bicycle_gnss_hop_get_fix(out)) {
        return true;
    }

    if (route_sim_get_fix(out)) {
        return true;
    }
    if (!out) {
        return false;
    }
    if (g_sim.thread_run) {
        pthread_mutex_lock(&g_sim.lock);
        *out = g_sim.fix;
        pthread_mutex_unlock(&g_sim.lock);
        return out->valid;
    }

    return false;
}"}

