 * @details 用户 2026-11-03："没有城区导航的偏航规划演示"。原来 `nav_warn`/`nav_replan`
 *          两个场景只是把横幅强设成那个状态，屏上没有路线、没有偏航、也没有新线。
 *          这里改成真实链路：
 *          1. `map_page_nav_plan_sim()` 在城区规划一条路线（恒丰路 → 城区东侧），
 *             路线模拟就是骑手；
 *          2. 骑 `BICYCLE_DEMO_REROUTE_RIDE_MS` 后，给**对外定位**加一个垂直于行进
 *             方向 `BICYCLE_DEMO_REROUTE_OFF_M`（120 m）的偏移；
 *          3. map_page 的偏航判定（阈值 `bicycle_config_nav_off_route_m()` = 50 m，
 *             持续 3 s）自己触发 reroute —— 横幅进"重新规划"、路线从新位置重画；
 *          4. 重规划落地后清掉偏移，骑手回到新路线上继续骑。
 *
 * @note 只作用于定位出口（`bicycle_gnss_sim_set_offset()`）；路线模拟自己的进度
 *       不受影响，`bicycle_route_sim_reload()` 会按新路线就近续上，不会瞬移回起点。
 */
static bool demo_enter_reroute_demo(void)
{
    map_page_t * page = lvgl_page_map();

    if (page == NULL) {
        syslog(LOG_WARNING, "demo: no map page for reroute\n");
        return false;
    }

    demo_scene_clear_ride();               /* 停上一段导航/回放/骑行 */
    demo_sim_reset();

    map_page_set_arrow_visible(page, true);
    if (!map_page_nav_plan_sim(page,
            BICYCLE_DEMO_CITY_FROM_LON, BICYCLE_DEMO_CITY_FROM_LAT,
            BICYCLE_DEMO_PLAN_LON, BICYCLE_DEMO_PLAN_LAT)) {
        syslog(LOG_WARNING, "demo: city plan sim failed\n");
        return false;
    }

    s_reroute_phase = 0;
    s_reroute_ms = lv_tick_get();
    s_reroute_move_ms = 0;
    syslog(LOG_INFO, "demo: reroute demo plan %.6f,%.6f -> %.6f,%.6f\n",
        BICYCLE_DEMO_CITY_FROM_LON, BICYCLE_DEMO_CITY_FROM_LAT,
        BICYCLE_DEMO_PLAN_LON, BICYCLE_DEMO_PLAN_LAT);
    return true;
}

/** @brief ④的节拍：等路线就绪 → 骑几秒 → 拉偏 → 等 repplanning → 落地清偏移。 */
static void demo_reroute_tick(void)
{
    map_page_t * page = lvgl_page_map();
    bool replanning;
    uint32_t el;

    if (page == NULL) {
        return;
    }

    el = lv_tick_elaps(s_reroute_ms);
    replanning = map_page_nav_replanning(page);

    if (s_reroute_phase == 0) {
        /* 冷机路网加载/规划要几秒：等路线模拟真的在跑再开始计"骑了多久"。 */
        if (s_reroute_move_ms == 0u && bicycle_route_sim_active()
            && map_page_nav_active(page)) {
            s_reroute_move_ms = lv_tick_get();
            if (s_reroute_move_ms == 0u) {
                s_reroute_move_ms = 1u;
            }
            syslog(LOG_INFO, "demo: reroute riding at %ums\n", (unsigned)el);
        }

        if (s_reroute_move_ms != 0u
            && lv_tick_elaps(s_reroute_move_ms) >= BICYCLE_DEMO_REROUTE_RIDE_MS) {
            bicycle_gnss_fix_t fix;
            double east = BICYCLE_DEMO_REROUTE_OFF_M;
            double north = 0.0;

            /* 沿行进方向右偏 90°：无论路线朝哪，off_route 都真的到 120 m。 */
            if (bicycle_runtime_poll_fix(&fix) && fix.valid) {
                const double th = (double)fix.course_deg * M_PI / 180.0;

                east = BICYCLE_DEMO_REROUTE_OFF_M * cos(th);
                north = -BICYCLE_DEMO_REROUTE_OFF_M * sin(th);
            }

            bicycle_gnss_sim_set_offset(east, north);
            s_reroute_phase = 1;
            syslog(LOG_INFO, "demo: reroute off-route e=%.0fm n=%.0fm\n",
                east, north);
        }
    } else if (s_reroute_phase == 1) {
        if (replanning) {
            s_reroute_phase = 2;
            syslog(LOG_INFO, "demo: reroute replanning started\n");
        } else if (el >= BICYCLE_DEMO_REROUTE_TIMEOUT_MS) {
            /* 没触发（路网缺数据/阈值被改大）：至少把偏移收回来，别带进下一步。 */
            bicycle_gnss_sim_set_offset(0.0, 0.0);
            s_reroute_phase = 3;
            syslog(LOG_WARNING, "demo: reroute not triggered in %ums\n",
                (unsigned)el);
        }
    } else if (s_reroute_phase == 2) {
        if (!replanning) {
            bicycle_gnss_sim_set_offset(0.0, 0.0);
            s_reroute_phase = 3;
            syslog(LOG_INFO, "demo: reroute done at %ums, offset cleared\n",
                (unsigned)el);
        }
    }
}

