            /* 沿行进方向右偏 90°：无论路线朝哪，off_route 都真的到 120 m。 */
            if (bicycle_runtime_poll_fix(&fix) && fix.valid) {
                const double th = (double)fix.course_deg * M_PI / 180.0;

                east = BICYCLE_DEMO_REROUTE_OFF_M * cos(th);
                north = -BICYCLE_DEMO_REROUTE_OFF_M * sin(th);
            }

            bicycle_gnss_sim_set_offset(east, north);
            s_reroute_phase = 1;
            s_reroute_off_seen = false;
            syslog(LOG_INFO, "demo: reroute off-route e=%.0fm n=%.0fm\n",
                east, north);
        }
    } else if (s_reroute_phase == 1) {
        /* 偏航真的被算出来了（120 m > 阈值）——留个判据。 */
        if (!s_reroute_off_seen && off_m >= BICYCLE_DEMO_REROUTE_OFF_M * 0.6) {
            s_reroute_off_seen = true;
            syslog(LOG_INFO, "demo: reroute off_route=%.0fm\n", off_m);
        }

        if (replanning) {
            s_reroute_phase = 2;
            syslog(LOG_INFO, "demo: reroute replanning started\n");
        } else if (s_reroute_off_seen && off_m <= BICYCLE_DEMO_REROUTE_OFF_M * 0.25) {
            /* 规划快到来不及看到 replanning 帧：新路线已经贴回来了 ⇒ 也算落地。 */
            bicycle_gnss_sim_set_offset(0.0, 0.0);
            s_reroute_phase = 3;
            syslog(LOG_INFO, "demo: reroute done (off_route back to %.0fm)\n", off_m);
            demo_tour_start(k_tour_ride, 4u, 4000u);
        } else if (el >= BICYCLE_DEMO_REROUTE_TIMEOUT_MS) {
            /* 没触发（路网缺数据/阈值被改大）：至少把偏移收回来，别带进下一步。 */
            bicycle_gnss_sim_set_offset(0.0, 0.0);
            s_reroute_phase = 3;
            syslog(LOG_WARNING, "demo: reroute not triggered in %ums\n",
                (unsigned)el);
            demo_tour_start(k_tour_ride, 4u, 4000u);
        }
    } else if (s_reroute_phase == 2) {
        if (!replanning) {
            bicycle_gnss_sim_set_offset(0.0, 0.0);
            s_reroute_phase = 3;
            /* 偏航/重规划已经演完，剩下的时间把主界面其余页轮一遍。 */
            demo_tour_start(k_tour_ride, 4u, 4000u);
            syslog(LOG_INFO, "demo: reroute done at %ums, offset cleared\n",
                (unsigned)el);
        }
    }
}"}

